import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div className="component-preview relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout">
      {children}
    </div>
  );
}

import * as React from "react";

import { Progress } from "@/registry/erbium/ui/progress";
import { Slider } from "@/registry/erbium/ui/slider";

export function ProgressControlled() {
  const [value, setValue] = React.useState(50);

  return (
    <div className="flex w-full max-w-sm flex-col gap-4">
      <Progress value={value} className="w-full" />
      <Slider
        value={value}
        onValueChange={(value) => setValue(value as number)}
        min={0}
        max={100}
        step={1}
      />
    </div>
  );
}

import * as React from "react";

import { Progress } from "@/registry/erbium/ui/progress";

export default function ProgressDemo() {
  const [progress, setProgress] = React.useState(13);

  React.useEffect(() => {
    const timer = setTimeout(() => setProgress(66), 500);
    return () => clearTimeout(timer);
  }, []);

  return <Progress value={progress} className="w-[60%]" />;
}

import { Progress, ProgressLabel, ProgressValue } from "@/registry/erbium/ui/progress";

export function ProgressWithLabel() {
  return (
    <Progress value={56} className="w-full max-w-sm">
      <ProgressLabel>Upload progress</ProgressLabel>
      <ProgressValue />
    </Progress>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Progress } from "@/registry/erbium/ui/progress";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { ProgressTrack, ProgressIndicator } from \"@/registry/erbium/ui/progress\";\nimport { Progress } from \"@/registry/erbium/ui/progress\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof Progress>) => (\n  <Progress\n    {...args}\n    className={`w-72 ${typeof args.className === \"string\" ? args.className : \"\"}`}\n  >\n    <ProgressTrack>\n      <ProgressIndicator />\n    </ProgressTrack>\n  </Progress>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/progress-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import PartialExample from "./variants/partial";

const PartialSource = "import { Progress } from \"@/registry/erbium/ui/progress\";\n\nconst Example = () => <Progress value={40} className=\"w-64\" aria-label=\"Upload progress\" />;\n\nexport default Example;\n";

import CompleteExample from "./variants/complete";

const CompleteSource = "import { Progress } from \"@/registry/erbium/ui/progress\";\n\nconst Example = () => <Progress value={100} className=\"w-64\" aria-label=\"Upload complete\" />;\n\nexport default Example;\n";

import LabelExample from "./variants/label";

const LabelSource = "import { ProgressWithLabel } from \"../examples/progress-label\";\n\nconst Example = () => <ProgressWithLabel />;\n\nexport default Example;\n";

import ControlledExample from "./variants/controlled";

const ControlledSource = "import { ProgressControlled } from \"../examples/progress-controlled\";\n\nconst Example = () => <ProgressControlled />;\n\nexport default Example;\n";

const meta = {
  component: Progress,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "Displays an indicator showing the completion progress of a task, typically displayed as a progress bar.\n\n**Import:** `@/registry/erbium/ui/progress`\n\n## Usage\n\n```tsx\nimport { Progress } from \"@/registry/erbium/ui/progress\";\n```\n\n```tsx\n<Progress value={33} />\n```\n\n## Composition\n\nUse `ProgressLabel` and `ProgressValue` to add a label and value display.\n\n```tsx\nimport { Progress, ProgressLabel, ProgressValue } from \"@/registry/erbium/ui/progress\";\n\n<Progress value={56} className=\"w-full max-w-sm\">\n  <ProgressLabel>Upload progress</ProgressLabel>\n  <ProgressValue />\n</Progress>;\n```\n\n```text\nProgress\n├── ProgressLabel\n├── ProgressValue\n└── ProgressTrack\n    └── ProgressIndicator\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Progress](https://base-ui.com/react/components/progress)",
      },
    },
  },
} satisfies Meta<typeof Progress>;

export default { ...meta, title: "Feedback & status/Progress",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Progress> = {
  args: { value: 45, className: "" },
  argTypes: { value: { control: { type: "range", min: 0, max: 100, step: 1 } } },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Partial: Story = {
  parameters: {
    docs: {
      description: { story: "Show a partially completed task." },
      source: { code: PartialSource },
    },
  },
  render: PartialExample,
};

export const Complete: Story = {
  parameters: {
    docs: {
      description: { story: "Show a completed task." },
      source: { code: CompleteSource },
    },
  },
  render: CompleteExample,
};

export const Label: Story = {
  parameters: {
    docs: {
      description: { story: "Use `ProgressLabel` and `ProgressValue` to add a label and value display." },
      source: { code: LabelSource },
    },
  },
  render: LabelExample,
};

export const Controlled: Story = {
  parameters: {
    docs: {
      description: { story: "A progress bar that can be controlled by a slider." },
      source: { code: ControlledSource },
    },
  },
  render: ControlledExample,
